from fastapi import APIRouter, Depends
router = APIRouter()

@router.post('/orders')
def create_order(token: str = Depends(oauth2_scheme)):
    payload = verify_token(token)
    tenant_id_context = payload['tenant_id']
    db_session.where(tenant_id=tenant_id_context)
    return {'status': 'created'}
